// Extract message data
const message = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;
const username = $input.first().json.message.from.username || 'Unknown';
const userId = $input.first().json.message.from.id;
const messageId = $input.first().json.message.message_id;

return [{
  json: {
    userMessage: message,
    chatId: chatId,
    username: username,
    userId: userId,
    messageId: messageId,
    timestamp: new Date().toISOString()
  }
}];

// Validation function
const input = $input.first().json;
const dataType = input.dataType; // 'problem' or 'why'
const data = input.data;

let isValid = false;
let quality = 'Poor';
let feedback = [];
let issues = [];

if (dataType === 'problem') {
  // Validate problem statement
  const length = data.length;
  const hasNumbers = /\d/.test(data);
  const hasKPI = /\b(aht|csat|nps|fcr|occupancy|utilization|abandonment|sla|handle time|wait time|transfer rate)\b/i.test(data);

  if (length >= 20) {
    feedback.push('✅ Length sufficient');
  } else {
    issues.push('❌ Too short (need 20+ characters)');
  }

  if (hasNumbers) {
    feedback.push('✅ Contains metrics');
  } else {
    issues.push('❌ Missing specific numbers/metrics');
  }

  if (hasKPI) {
    feedback.push('✅ Identifies KPI');
  }

  isValid = length >= 20 && hasNumbers;
  quality = isValid && hasKPI ? 'Excellent' : isValid ? 'Good' : 'Poor';

} else if (dataType === 'why') {
  // Validate WHY data
  const initialAnswer = data.initialAnswer || '';
  const dataGathered = data.dataGathered || '';
  const validatedAnswer = data.validatedAnswer || '';

  const hasInitialAnswer = initialAnswer.length >= 10;
  const hasDataGathered = dataGathered.length >= 20;
  const hasValidatedAnswer = validatedAnswer.length >= 10;
  const hasNumbers = /\d/.test(dataGathered);
  const isDetailed = dataGathered.length >= 50;

  if (hasInitialAnswer) {
    feedback.push('✅ Initial Answer provided');
  } else {
    issues.push('❌ Initial Answer too short (need 10+ characters)');
  }

  if (hasDataGathered) {
    feedback.push('✅ Data Gathered provided');
  } else {
    issues.push('❌ Data Gathered too short (need 20+ characters)');
  }

  if (hasValidatedAnswer) {
    feedback.push('✅ Validated Answer provided');
  } else {
    issues.push('❌ Validated Answer too short (need 10+ characters)');
  }

  if (hasNumbers) {
    feedback.push('✅ Contains metrics/numbers');
  } else {
    issues.push('⚠️ No metrics found (data should include numbers)');
  }

  if (isDetailed) {
    feedback.push('🌟 Detailed data collection');
  }

  isValid = hasInitialAnswer && hasDataGathered && hasValidatedAnswer;

  if (isValid && hasNumbers && isDetailed) {
    quality = 'Excellent';
  } else if (isValid && hasNumbers) {
    quality = 'Good';
  } else if (isValid) {
    quality = 'Acceptable';
  } else {
    quality = 'Poor';
  }
}

return [{
  json: {
    isValid: isValid,
    quality: quality,
    feedback: feedback.join('\n'),
    issues: issues.join('\n'),
    score: quality === 'Excellent' ? 5 : quality === 'Good' ? 4 : quality === 'Acceptable' ? 3 : quality === 'Poor' ? 2 : 1
  }
}];
